script:
(function () {
  'use strict';
  // CD ladder. The deposit is split equally across the rungs (cents rounded down, remainder on
  // the last rung). Each CD grows at its APY, which already includes compounding:
  //   value = principal x (1 + APY)^(months / 12), rounded to the cent at maturity.
  // With reinvestment on, every CD maturing within the chosen number of years rolls its full
  // value into a new CD of the chosen term and APY; later maturities are paid out.
  // Checks: $10,000 at 4% APY for 24 months = $10,816.00; for 18 months = $10,605.96;
  // $50,000 over five rungs (12-60 months) at 4% each: interest 400 + 816 + 1,248.64 +
  // 1,698.59 + 2,166.53 = $6,329.76; a 12-month rung reinvested twice more at 4% = 10,000 x 1.04^3.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var MAX_RUNGS = 10;
  var DEFAULT_RUNGS = [[12, 3.9], [24, 3.8], [36, 3.7], [48, 3.7], [60, 3.8]];
  var rowCounter = 0;

  function round2(x) { return Math.round(x * 100) / 100; }

  function grow(principal, apy, months) { return round2(principal * Math.pow(1 + apy, months / 12)); }

  function splitEqually(total, n) {
    var cents = Math.round(total * 100), base = Math.floor(cents / n), out = [];
    for (var i = 0; i < n; i++) out.push((i === n - 1 ? cents - base * (n - 1) : base) / 100);
    return out;
  }

  // rungs: [{term: months, apy: decimal}]; re: {on, term, apy, years}
  function ladder(deposit, rungs, re) {
    var amounts = splitEqually(deposit, rungs.length);
    var horizon = re.on ? re.years * 12 : 0;
    var events = [], interest = 0, paid = 0, firstRound = 0;
    rungs.forEach(function (r, i) {
      var start = 0, principal = amounts[i], term = r.term, apy = r.apy, round = 0;
      for (;;) {
        var month = start + term;
        var value = grow(principal, apy, term);
        if (round === 0) firstRound += value - principal;
        interest += value - principal;
        var reinvest = re.on && month <= horizon;
        events.push({ month: month, rung: i + 1, principal: principal, value: value, reinvest: reinvest });
        if (!reinvest) { paid += value; break; }
        start = month; principal = value; term = re.term; apy = re.apy; round++;
      }
    });
    events.sort(function (a, b) { return a.month - b.month || a.rung - b.rung; });
    return {
      amounts: amounts, events: events, interest: round2(interest), paid: round2(paid),
      firstRound: round2(firstRound), first: events[0].month, last: events[events.length - 1].month
    };
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function termText(m) {
    if (m % 12 === 0) { var y = m / 12; return y + (y === 1 ? ' year' : ' years'); }
    return m + (m === 1 ? ' month' : ' months');
  }

  function pct(x) { return (x * 100).toFixed(2) + '%'; }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clear(id) {
    var el = document.getElementById(id);
    while (el.firstChild) el.removeChild(el.firstChild);
    return el;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  // ---- Rung rows (built with DOM methods) ----
  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, step, min, max, mode) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = min; input.max = max; input.step = step; input.inputMode = mode;
    input.value = String(value);
    input.setAttribute('data-field', id.replace(/\d+$/, ''));
    group.appendChild(input);
    group.appendChild(el('span', 'input-affix', affix));
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addRung(term, apy) {
    var list = document.getElementById('clRungs');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-rung-row', String(n));
    var head = el('div', 'flex items-center justify-between gap-3');
    var title = el('p', 'text-sm font-semibold text-ink', 'Rung');
    title.setAttribute('data-rung-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-rung-row]').length <= 1) return;
      list.removeChild(row);
      refreshRows();
      update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);
    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('clTerm' + n, 'Term', term, 'months', '1', '1', '120', 'numeric'));
    pair.appendChild(numberField('clApy' + n, 'APY', apy, '%', '0.05', '0', '20', 'decimal'));
    row.appendChild(pair);
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('clRungs').querySelectorAll('[data-rung-row]');
    for (var i = 0; i < rows.length; i++) {
      rows[i].querySelector('[data-rung-title]').textContent = 'Rung ' + (i + 1);
      var btn = rows[i].querySelector('[data-remove]');
      btn.disabled = rows.length <= 1;
      btn.setAttribute('aria-label', 'Remove rung ' + (i + 1));
    }
    document.getElementById('clAdd').disabled = rows.length >= MAX_RUNGS;
  }

  function readRungs() {
    var rows = document.getElementById('clRungs').querySelectorAll('[data-rung-row]'), out = [];
    for (var i = 0; i < rows.length; i++) {
      var term = parseFloat(rows[i].querySelector('[data-field="clTerm"]').value);
      var apy = parseFloat(rows[i].querySelector('[data-field="clApy"]').value);
      if (isNaN(term) || term < 1 || term > 120 || Math.round(term) !== term) return 'Enter each rung term as whole months from 1 to 120.';
      if (isNaN(apy) || apy < 0 || apy > 20) return 'Enter each rung APY from 0 to 20%.';
      out.push({ term: term, apy: apy / 100 });
    }
    return out;
  }

  function blank() {
    ['clInterest', 'clTotal', 'clAvgApy', 'clLast', 'clEach', 'clFirst', 'clFirstRound'].forEach(function (id) { set(id, '–'); });
    clear('clRungTable'); clear('clSchedule');
  }

  function update() {
    var on = document.getElementById('clReinvest').checked;
    document.getElementById('clReinvestWrap').hidden = !on;
    var deposit = parseFloat(document.getElementById('clDeposit').value);
    var reTerm = parseFloat(document.getElementById('clReTerm').value);
    var reApy = parseFloat(document.getElementById('clReApy').value);
    var years = parseFloat(document.getElementById('clYears').value);
    var rungs = readRungs();
    var msg = '';
    if (isNaN(deposit) || deposit <= 0 || deposit > 1e10) msg = 'Enter an amount to invest above $0.';
    else if (typeof rungs === 'string') msg = rungs;
    else if (deposit * 100 < rungs.length) msg = 'Enter at least one cent for each rung.';
    else if (on && (isNaN(reTerm) || reTerm < 3 || reTerm > 120 || Math.round(reTerm) !== reTerm)) msg = 'Enter a new CD term of 3 to 120 whole months.';
    else if (on && (isNaN(reApy) || reApy < 0 || reApy > 20)) msg = 'Enter a new CD APY from 0 to 20%.';
    else if (on && (isNaN(years) || years < 1 || years > 30 || Math.round(years) !== years)) msg = 'Enter 1 to 30 whole years of reinvesting.';
    var error = document.getElementById('clError');
    error.hidden = !msg;
    if (msg) { error.textContent = msg; blank(); return; }

    var r = ladder(deposit, rungs, { on: on, term: reTerm, apy: reApy / 100, years: years });
    var avg = rungs.reduce(function (s, x) { return s + x.apy; }, 0) / rungs.length;
    set('clInterest', money.format(r.interest));
    set('clTotal', money.format(r.paid));
    set('clAvgApy', pct(avg));
    set('clLast', dateAfter(r.last));
    var minA = r.amounts[0], maxA = r.amounts[r.amounts.length - 1];
    set('clEach', minA === maxA ? money.format(minA) : money.format(minA) + ' (last rung ' + money.format(maxA) + ')');
    set('clFirst', dateAfter(r.first));
    set('clFirstRound', money.format(r.firstRound));

    var rt = clear('clRungTable');
    rungs.forEach(function (x, i) {
      var v = grow(r.amounts[i], x.apy, x.term);
      addRow(rt, ['Rung ' + (i + 1), termText(x.term), pct(x.apy), money.format(r.amounts[i]), dateAfter(x.term), money.format(v - r.amounts[i]), money.format(v)]);
    });
    var sc = clear('clSchedule');
    var action = 'Reinvested for ' + termText(reTerm) + ' at ' + pct(reApy / 100);
    r.events.forEach(function (e) {
      addRow(sc, [dateAfter(e.month), 'Rung ' + e.rung, money.format(e.principal), money.format(e.value - e.principal), money.format(e.value), e.reinvest ? action : 'Paid out']);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULT_RUNGS.forEach(function (r) { addRung(r[0], r[1]); });
    var form = document.getElementById('clForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('clAdd').addEventListener('click', function () {
      var rows = document.getElementById('clRungs').querySelectorAll('[data-rung-row]');
      if (rows.length >= MAX_RUNGS) return;
      var last = rows.length ? rows[rows.length - 1] : null;
      var lastTerm = last ? parseFloat(last.querySelector('[data-field="clTerm"]').value) : 0;
      var lastApy = last ? last.querySelector('[data-field="clApy"]').value : '4';
      addRung(isNaN(lastTerm) ? 12 : Math.min(120, lastTerm + 12), lastApy || '4');
      update();
    });
    update();
  });
})();
